CREATE TABLE IF NOT EXISTS operational_twin_snapshots (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, snapshot_kind TEXT NOT NULL CHECK(snapshot_kind IN ('on_demand','scenario')), state_json TEXT NOT NULL, state_sha256 TEXT NOT NULL, source_counts_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_twin_org_created ON operational_twin_snapshots(organization_id,created_at);
CREATE TABLE IF NOT EXISTS decision_replays (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, decision_type TEXT NOT NULL, input_json TEXT NOT NULL, rules_json TEXT NOT NULL, outcome_json TEXT NOT NULL, decision_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), replayed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_decision_replays_org_created ON decision_replays(organization_id,created_at);
CREATE TABLE IF NOT EXISTS scenario_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, scenario_json TEXT NOT NULL, baseline_sha256 TEXT NOT NULL, result_json TEXT NOT NULL, result_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_scenario_runs_org_created ON scenario_runs(organization_id,created_at);
CREATE TABLE IF NOT EXISTS skill_certifications (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill TEXT NOT NULL, certificate_ref TEXT NOT NULL, issuer TEXT NOT NULL, issued_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, status TEXT NOT NULL CHECK(status IN ('active','expired','revoked')), evidence_sha256 TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id,certificate_ref));
CREATE INDEX IF NOT EXISTS idx_skill_cert_org_user ON skill_certifications(organization_id,user_id,status,expires_at);
CREATE TABLE IF NOT EXISTS capacity_plans (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, plan_date DATE NOT NULL, parameters_json TEXT NOT NULL, result_json TEXT NOT NULL, result_sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,plan_date));
CREATE INDEX IF NOT EXISTS idx_capacity_plans_org_date ON capacity_plans(organization_id,plan_date);
